import type { Position } from "./player-types";

/**
 * Historical stylistic comparisons. Every entry carries the frame it applies to
 * and the grade band it belongs in, so a 5'10" passer never gets compared to a
 * 6'6" pocket thrower and a day-three prospect never gets an All-Pro comp.
 *
 * Comparisons are about the fictional player's projected style only.
 */
export type Comp = {
  name: string;
  program: string;
  minHeight: number;
  maxHeight: number;
  minWeight: number;
  maxWeight: number;
  minTier: number;
  maxTier: number;
  note: string;
  /**
   * Prototype field: a short "where they ended up" line for the small set of
   * comps where the real player's career is itself part of the story — not
   * populated on most entries yet, pending a decision on whether to expand it.
   */
  retro?: string;
};

