function distanceOutside(value: number, min: number, max: number): number {
  if (value < min) return min - value;
  if (value > max) return value - max;

  return 0;
}

/**
 * Scores every comparison in the position's pool on how far the player sits
 * outside its frame and grade window, then picks at random among the closest
 * few. Scoring rather than progressive relaxation is what stops a day-three
 * lineman from being handed an All-Pro comp when no exact match exists.
 */
export function findComp(
  pool: Comp[],
  height: number,
  weight: number,
  tier: number,
  choose: <T>(items: readonly T[], fallback: T) => T,
): Comp | null {
  if (pool.length === 0) {
    return null;
  }

  const scored = pool.map((comp) => {
    const heightPenalty = distanceOutside(height, comp.minHeight, comp.maxHeight);
    const weightPenalty = distanceOutside(weight, comp.minWeight, comp.maxWeight) / 12;
    const tierPenalty = distanceOutside(tier, comp.minTier, comp.maxTier) * 1.8;

    return { comp, penalty: heightPenalty + weightPenalty + tierPenalty };
  });

  const best = Math.min(...scored.map((entry) => entry.penalty));
  const shortlist = scored
    .filter((entry) => entry.penalty <= best + 0.75)
    .map((entry) => entry.comp);

  return choose(shortlist, shortlist[0] as Comp);
}

export function formatComp(comp: Comp | null): string {
  if (!comp) {
    return "No clean historical comparison";
  }

  return comp.name + " (" + comp.program + ") — " + comp.note;
}
